import frappe
from frappe.model.document import Document


class UIQuotationEvaluation(Document):
	def validate(self):
		# Snapshots are generated by the server, never from browser-supplied data.
		if not frappe.flags.get("creating_quotation_evaluation"):
			frappe.throw("Evaluation snapshots can only be created by the comparison service.")


def has_permission(doc, ptype=None, user=None, debug=False):
	user = user or frappe.session.user
	if not doc or doc.owner != user:
		return False
	try:
		names = frappe.parse_json(doc.quotation_names)
		return isinstance(names, list) and bool(names) and all(
			frappe.has_permission("Supplier Quotation", "read", doc=frappe.get_doc("Supplier Quotation", name), user=user)
			for name in names
		) and frappe.has_permission("Company", "read", doc=frappe.get_doc("Company", doc.company), user=user)
	except Exception:
		return False


def permission_query_conditions(user=None):
	"""Allow Desk lists only for snapshots whose sources the owner can read."""
	user = user or frappe.session.user
	try:
		names = frappe.get_all(
			"UI Quotation Evaluation", filters={"owner": user}, pluck="name", limit_page_length=0
		)
		permitted = [name for name in names if has_permission(frappe.get_doc("UI Quotation Evaluation", name), user=user)]
		if not permitted:
			return "1=0"
		escaped = ", ".join(frappe.db.escape(name) for name in permitted)
		return f"`tabUI Quotation Evaluation`.`name` in ({escaped})"
	except Exception:
		# A permission or database failure must not disclose saved comparisons.
		return "1=0"


def ai_request_query_conditions(user=None):
	# AI request payloads remain available only through explicitly checked documents.
	return "1=0"
